#include <stdio.h>
#include <string.h>

void contadorDeVogais(void) {
    char palavra[50] = "";
    scanf("%49s", palavra);
    int vogais = 0;
    int n = strlen(palavra);
    for (int i = 0; i < n; i++) {
        char letra = palavra[i];
        if (letra == 'a' || letra == 'e' || letra == 'i' || letra == 'o' || letra == 'u') {
            vogais++;
        }
    }
    printf("%d\n", vogais);
}
